import fs from 'node:fs';import * as THREE from 'three';
export function furnitureSource(floor){const b=fs.readFileSync(new URL(`../../public${floor.url}`,import.meta.url)),n=b.readUInt32LE(12),g=JSON.parse(b.subarray(20,20+n)),bin=b.subarray(28+n),geo=new THREE.BufferGeometry();for(const[k,name]of[['POSITION','position'],['NORMAL','normal'],['COLOR_0','color']]){const ac=g.accessors[g.meshes.find(m=>m.name==='furniture').primitives[0].attributes[k]],v=g.bufferViews[ac.bufferView],a=new Float32Array(ac.count*3);for(let i=0;i<a.length;i++)a[i]=bin.readFloatLE((v.byteOffset||0)+(ac.byteOffset||0)+i*4);geo.setAttribute(name,new THREE.BufferAttribute(a,3));}return new THREE.Mesh(geo);}